            nGoldBank = D2Common::Stats::StatsEx::STATSEX_GetCurrentStat(UNIT::Player::GetPlayerUnit_UI(), eGoldStatType, nStatLayer);
            nStatLayer = 0;
            eGoldStatType = UNITSTAT_gold;
            pPlayer = UNIT::Player::GetPlayerUnit_UI();
