    static uint32_t gnCursorItemAnimDrawOffset; D2_STATIC_GUARD_BSS(gnCursorItemAnimDrawOffset, "D2Client::UI::ui::UI_DrawCursorWithItem::gnCursorItemAnimDrawOffset");

    int32_t nClampedY;
    uint32_t nDimension;
